public class Tree {
    /**
    * Performs a right node rotation.
    * @param node a node to rotate
    * @return a new parent of the {@code node}
    */
    private TreeNode<T> rotateRight(TreeNode<T> node){
        // Check if the node is part of a tree
        if (node == null) {
            return null;
        }

        // Get the left child of the node
        TreeNode<T> left = node.getLeft();

        // If the left child is null, return the node
        if (left == null) {
            return node;
        }

        // Get the right child of the left child
        TreeNode<T> right = left.getRight();

        // Set the parent of the right child to the node
        left.setRight(node);

        // Set the left child of the node to the right child of the node
        node.setLeft(right);

        // Return the new parent of the node
        return left;
    }
}

