public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Create a new mapping from the input graph to itself
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>(graph);

    // Iterate over the vertices in the input graph
    for (V vertex : graph.getVertices()) {
        // Add a self-loop mapping to the new mapping
        mapping.addMapping(vertex, vertex);
    }

    return mapping;
