public static void scheduleForceDeleteOnExit(File file) throws IOException {

    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    Path path = file.toPath();
    Files.walkFileTree(path, new SimpleFileVisitor<>() {
        @Override
        public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
            try {
                Files.delete(file);
            } catch (IOException ex) {
                throw new IOException("Failed to delete " + file, ex);
            }
            return FileVisitResult.CONTINUE;
        }
        @Override
        public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
            try {
                Files.delete(dir);
            } catch (IOException ex) {
                throw new IOException("Failed to delete " + dir, ex);
            }
            return FileVisitResult.CONTINUE;
        }
    });
}

/**
* Schedules a file to be deleted when JVM exits. If file is directory delete it and all sub-directories.
* @param file  file or directory to delete, must not be {@code null}
* @throws NullPointerException if the file is {@code null}
* @throws IOException in case deletion is unsuccessful
*/
public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File is null.");
    }

    if (file.isDirectory()) {
        // Delete directory if it exists
        if (file.exists()) {
            forceDelete(file);
        }

        // Deleting sub-directories
        File[] files = file.listFiles();
        if (files != null) {
            for (File subFile : files) {
                forceDeleteOnExit(subFile);
            }
        }
    } else {
        // Delete file if it exists
        if (file.exists()) {
            forceDelete(file);
        }
    }
}

/**
* Deletes a file or directory recursively if it exists.
* @param file  file or directory to delete, must not be {@code null}
* @throws NullPointerException if the file is {@code null}
* @throws IOException in case deletion is unsuccessful
*/
private static void forceDelete(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File is null.");
    }

    // Delete file if it exists
    if (file.exists()) {
        if (file.isDirectory()) {
            // Deleting sub-directories
            File[] files = file.listFiles();
            if (files != null) {
                for (File subFile : files) {
                    forceDelete(subFile);
                }
            }
        }

        // Deleting file
        boolean deleted = file.delete();
        if (!deleted) {
            throw new IOException("Failed to delete file " + file);
        }
    }
}

