public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Skip the leading '/' if the path is absolute
    int startIndex = u.getPath().charAt(0) == '/' ? 1 : 0;

    // Split the URI path into segments based on '/'
    String[] pathSegmentsStr = u.getPath().substring(startIndex).split("/");

    // Decode each segment if necessary
    if (decode) {
        for (int i = 0; i < pathSegmentsStr.length; i++) {
            pathSegmentsStr[i] = URLDecoder.decode(pathSegmentsStr[i], "UTF-8");
        }
    }

    // Create PathSegmentImpl objects from the decoded segments
    for (String pathSegmentStr : pathSegmentsStr) {
        pathSegments.add(new PathSegmentImpl(pathSegmentStr));
    }

    return pathSegments;
}

