      throw new IllegalArgumentException("The desired capacity must be a positive integer.");
   }

   // Initialize the lower and upper bounds
   int lowerBound = 1;
   int upperBound = desiredCapacity;

   // Find the closest prime number to the desired capacity
   while (lowerBound < upperBound) {
      int mid = (lowerBound + upperBound) / 2;
      if (isPrime(mid)) {
         // If the mid point is prime, return it if it is greater than or equal to the desired capacity
         if (mid >= desiredCapacity) {
            return mid;
         }
         // If the mid point is not prime, update the lower bound
         else {
            lowerBound = mid + 1;
