    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer");
    }

    // Initialize the next prime variable
    int nextPrime = 1;

    // Loop through the numbers from 2 to the desired capacity
    for (int i = 2; i <= desiredCapacity; i++) {
        // Check if the number is prime
        boolean isPrime = true;
        for (int j = 2; j < i; j++) {
            if (i % j == 0) {
