private List<Pair<List<Pair<Integer, Integer>>, E>> computeSeparators(E e, Graph<Integer, E> graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> separators = new ArrayList<>();

    // Iterate over all pairs of vertices connected by the edge
    for (E euv : graph.edgesOf(e.getFirst())) {
        List<Pair<List<Pair<Integer, Integer>>, E>> separatorsForEdge = new ArrayList<>();

        // Compute minimal separators for each pair of vertices
        for (E euv : graph.edgesOf(e.getSecond())) {
            // If the edge is not the same as the current edge, compute the minimal separators for the edge
            if (!euv.equals(e)) {
                separatorsForEdge.addAll(computeSeparators(euv, graph));
            }
        }

        separators.add(new Pair<>(separatorsForEdge, euv));
    }

    return separators;
}

