  for (int v = 0; v < graph.getVertexCount(); v++) {
    if (v != edge.getFirst() && v != edge.getSecond()) {
      separators.add(new Pair<>(v, edge.getFirst()));
      separators.add(new Pair<>(v, edge.getSecond()));
    }
  }
