private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
	// Create a new list to store the result
	List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();

	// Loop through all edges in the graph
	for(E edge : graph.edgeSet()){
		// Get the neighbors of the edge
		Set<Integer> neighbors = graph.getNeighbors(edge.v1);

		// Compute the minimum separators for each neighbor
		List<Pair<List<Pair<Integer,Integer>>,Integer>> minSeparators = new ArrayList<>();
		for(Integer neighbor : neighbors){
			// Compute the separator list for the neighbor
			List<Pair<Integer,Integer>> separatorListForNeighbor = computeSeparatorList(edge, neighbor);

			// Add the separator list for the neighbor to the list of all separators
			minSeparators.add(new Pair<>(separatorListForNeighbor, neighbor));
		}

		// Sort the list of separators by the size of the separator list
		Collections.sort(minSeparators, new Comparator<Pair<List<Pair<Integer,Integer>>,Integer>>(){
			@Override
			public int compare(Pair<List<Pair<Integer,Integer>>,Integer> p1, Pair<List<Pair<Integer,Integer>>,Integer> p2){
				return p1.getKey().size() - p2.getKey().size();
			}
		});

		// Concatenate the list of separators for each neighbor
		List<Pair<Integer,Integer>> globalSeparatorList = new ArrayList<>();
		for(Pair<List<Pair<Integer,Integer>>,Integer> separator : minSeparators){
			globalSeparatorList.addAll(separator.getKey());
		}

		// Add the global separator list for the edge to the list of all global separator lists
		separatorList.add(new Pair<>(globalSeparatorList, edge));
	}

	return separatorList;
}

/**
* Computes the separator list of the edge $e$ and its neighbor $v$. More precisely, for every edge $e$ and its neighbor $v$ computes a list of separators $S_e(v)$, where $S_e(v)$ is $\emptyset$ if $v$ is not a neighbor of $e$.
* @param edge the edge whose separator list is to be computed
* @param v the vertex $v$ such that $v$ is a neighbor of $e$
* @return the separator list of $e$ and $v$, or $\emptyset$ if $v$ is not a neighbor of $e$
*/
private List<Pair<Integer,Integer>> computeSeparatorList(E edge, Integer v){
	// Check if $v$ is a neighbor of $e$
	if(!graph.neighborsContains(edge.v1, v)){
		return Collections.emptyList();
	}

	// Compute the separator list for the edge (v, w)
	List<Pair<Integer,Integer>> separatorList = new ArrayList<>();
	for(Integer w : graph.getNeighbors(v)){
		if(!w.equals(edge.v2)){
			separatorList.add(new Pair<>(w, v));
		}
	}

	return separatorList;
}

