*/
private int computeNumberOfEdgesNotCovered(List<Pair<List<Pair<Integer,Integer>>,E>> separators){
	int numberOfEdgesNotCovered = 0;

	// Loop through all edges in the graph
	for(E edge : graph.edgeSet()){
		// Check if the edge is not covered by any separator list
		boolean covered = false;
		for(Pair<List<Pair<Integer,Integer>>,E> separator : separators){
			if(separator.getValue().equals(edge)){
				covered = true;
				break;
			}
		}

		// If the edge is not covered, then it is not counted
		if(!covered){
			numberOfEdgesNotCovered++;
		}
	}

	return numberOfEdgesNotCovered;
}

