            continue;
        }
        // Check if the line is a time range
        if (line.matches(".*\\d\\s*:\\s*\\d\\d\\d\\d")) {
            // Extract the time range from the line
            String[] timeRangeParts = line.split("\\s*:\\s*");
            long startTimeInNanos = ChronoUnit.MILLIS.toNanos(Long.parseLong(timeRangeParts[0]));
            long endTimeInNanos = ChronoUnit.MILLIS.toNanos(Long.parseLong(timeRangeParts[1]));
            // Filter the time ranges based on the input
            List<ProfileAnalyzeTimeRange> filteredTimeRanges = timeRanges.stream()
                    .filter(tr -> tr.getStartTimeInNanos() <= startTimeInNanos && tr.getEndTimeInNanos() >= endTimeInNanos)
                    .collect(Collectors.toList());
            if (filteredTimeRanges.isEmpty()) {
                continue;
            }
            // Parse the thread snapshot from the line
            ThreadSnapshot threadSnapshot = parseThreadSnapshotFromLine(line, filteredTimeRanges.get(0));
            // Add the thread snapshot to the result
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
