public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file exists
    if (!file.exists()) {
        throw new FileNotFoundException("File does not exist");
    }

    // Check if the time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid time ranges");
    }

    // Read the file content
    List<String> lines = Files.readAllLines(file.toPath(), StandardCharsets.UTF_8);

    // Create a map to store the thread snapshots by thread name
    Map<String, ThreadSnapshot> threadSnapshotsMap = new HashMap<>();

    // Iterate over the file content and add the thread snapshots to the map
    for (String line : lines) {
        // Skip empty lines and lines that are not starting with "ThreadSnapshot"
        if (line.trim().isEmpty() || !line.startsWith("ThreadSnapshot")) {
