        }

        // Parse the thread snapshot information
        ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);

        // Check if the thread snapshot is within the time range
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.getStartTime() <= threadSnapshot.getTimestamp() && threadSnapshot.getTimestamp() <= timeRange.getEndTime()) {
                // Add the thread snapshot to the map
                threadSnapshotsMap.put(threadSnapshot.getThreadName(), threadSnapshot);
                break;
            }
        }
    }

