public static ThreadSnapshot parseThreadSnapshot(String line) {
    // Split the line into tokens
    String[] tokens = line.split(" ");

    // Check if the line has the correct number of tokens
    if (tokens.length < 9) {
        throw new IllegalArgumentException("Invalid thread snapshot");
    }

    // Parse the thread snapshot information
    ThreadSnapshot threadSnapshot = new ThreadSnapshot();
    threadSnapshot.setThreadName(tokens[0]);
    threadSnapshot.setTimestamp(Long.parseLong(tokens[1]));
    threadSnapshot.setLockName(tokens[2]);
    threadSnapshot.setLockOwner(tokens[3]);
    threadSnapshot.setLockMode(tokens[4]);
    threadSnapshot.setHoldCount(Integer.parseInt(tokens[5]));
    threadSnapshot.setRecursions(Integer.parseInt(tokens[6]));
    threadSnapshot.setBlockedCount(Integer.parseInt(tokens[7]));
    threadSnapshot.setWaitingCount(Integer.parseInt(tokens[8]));

    // Return the thread snapshot
    return threadSnapshot;
