private static List<ThreadSnapshot> parseFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    try (FileReader reader = new FileReader(file)) {
        BufferedReader br = new BufferedReader(reader);
        String line;
        while ((line = br.readLine()) != null) {
            String[] parts = line.split(",");
            if (parts.length > 2) {
                try {
                    long threadId = Long.parseLong(parts[0]);
                    String threadName = parts[1];
                    long startTime = Long.parseLong(parts[2]);
                    long endTime = Long.parseLong(parts[3]);
                    float cpuUsage = Float.parseFloat(parts[4]);

                    ProfileAnalyzeTimeRange timeRange = getTimeRange(timeRanges, startTime, endTime);
                    if (timeRange != null) {
                        ThreadSnapshot snapshot = new ThreadSnapshot(threadId, threadName, startTime, endTime, cpuUsage);
                        timeRange.addThreadSnapshot(snapshot);
                        snapshots.add(snapshot);
                    }
                } catch (NumberFormatException e) {
                    // ignore invalid lines
                }
            }
        }
    }

    return snapshots;
}

private static ProfileAnalyzeTimeRange getTimeRange(List<ProfileAnalyzeTimeRange> timeRanges, long startTime, long endTime) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.getStartMs() <= startTime && timeRange.getEndMs() >= endTime) {
            return timeRange;
        }
    }

    return null;
}
